const titleCase=s=>s?String(s).slice(0,1).toUpperCase()+String(s).slice(1):'';
const fmtNum=n=>Number(n||0).toLocaleString();
const cleanFileName=s=>String(s||'file').replace(/[^a-zA-Z0-9._-]/g,'_').slice(0,80);
